import json
import numpy as np
s=json.load(open('/app/output/spec.json'))
p=s['cameras']['room_camera']['pose']
c=np.array(p['position_m']); f=np.array(p['forward']); u=np.array(p['up']); r=np.array(p['right'])
fl=128/np.tan(np.deg2rad(22.5))
def unproject(x,y,z):
 d=f+(x-127.5)/fl*r-(y-127.5)/fl*u
 return c+(z-c[2])/d[2]*d
def project(v):
 d=np.array(v)-c
 return np.array([127.5+fl*np.dot(d,r)/np.dot(d,f),127.5-fl*np.dot(d,u)/np.dot(d,f)])
if __name__=='__main__':
 for pt in [(175,177),(193,188),(216,182),(199,171)]: print(pt,unproject(*pt,0))
 for pt in [(177,146),(195,154),(220,149),(201,142)]: print('seat',pt,unproject(*pt,.5))
 for z in [0,1,1.05,1.1]: print(z,project([0,0,z]))
